create table if not exists profiles (id uuid primary key, email text unique not null, display_name text not null, role text not null check (role in ('mentor','learner')), created_at timestamptz default now());
create table if not exists skills (id text primary key, sequence integer not null, topic text not null, world text not null, activity_percent numeric default 0, verified_stage text default 'discovering', source_sheet text, source_row integer, archived_at timestamptz);
create table if not exists quests (id uuid primary key default gen_random_uuid(), title text not null, description text, category text not null, status text not null default 'planned', due_date date, expected_minutes integer, actual_minutes integer, requires_approval boolean default false, created_by uuid references profiles(id), created_at timestamptz default now(), archived_at timestamptz);
create table if not exists time_logs (id uuid primary key default gen_random_uuid(), date date not null, duration_minutes integer not null, category text not null, quest_id uuid references quests(id), skill_id text references skills(id), description text, created_by uuid references profiles(id), created_at timestamptz default now());
create table if not exists submissions (id uuid primary key default gen_random_uuid(), quest_id uuid not null references quests(id), submitted_by uuid not null references profiles(id), reflection text, evidence_urls jsonb default '[]'::jsonb, submitted_at timestamptz default now());
create table if not exists approvals (id uuid primary key default gen_random_uuid(), submission_id uuid not null references submissions(id), reviewer_id uuid not null references profiles(id), decision text not null check (decision in ('approved','needs_revision')), feedback text, reviewed_at timestamptz default now());
